using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.EntityFrameworkCore;
using mC_Connect_table.Data;
using mC_Connect_table.Models;
using Microsoft.EntityFrameworkCore.Query.SqlExpressions;
using System.Text;
using System.Text.Json;

namespace mC_Connect_table.Controllers
{
    public class RestaurantTablesController : Controller
    {
        private readonly RestaurantTablesContext _context;
        private readonly HttpClient _httpClient;

        public RestaurantTablesController(RestaurantTablesContext context, HttpClient httpClient)
        {
            _context = context;
            _httpClient = httpClient;
        }

        // PUT: /RestaurantTables/SetTableStatus/5
        [HttpPut("/RestaurantTables/SetTableStatus/{id}")]
        public IActionResult SetTableStatus(int id, bool isActive, string? customerName = null)
        {
            var table = _context.RestaurantTables.Find(id);

            if (table == null)
            {
                return NotFound("Table not found.");
            }

            if (isActive)
            {
                // Seating the customer, so set the table as occupied
                table.IsActive = true;
                table.CustomerName = customerName ?? throw new ArgumentNullException(nameof(customerName), "Customer name is required when setting the table as active.");
                table.CurrentSessionId = Guid.NewGuid().ToString(); // Generate a unique session ID

                _context.SaveChanges();

                return Ok($"Table {id} is now occupied by {customerName}.");
            }
            else
            {
                // Clearing the table, so mark it as unoccupied
                table.IsActive = false;
                table.CustomerName = null;
                table.CurrentSessionId = null; // Clear session ID

                _context.SaveChanges();

                return Ok($"Table {id} is now cleared.");
            }
        }


        // GET: RestaurantTables
        public async Task<IActionResult> Index()
        {
            return View(await _context.RestaurantTables.ToListAsync());
        }

        // GET: RestaurantTables/Details/5
        public async Task<IActionResult> Details(int? id)
        {
            if (id == null)
            {
                return NotFound();
            }

            var restaurantTables = await _context.RestaurantTables
                .FirstOrDefaultAsync(m => m.TableNumber == id);
            if (restaurantTables == null)
            {
                return NotFound();
            }

            return View(restaurantTables);
        }

        // GET: RestaurantTables/Create
        public IActionResult Create()
        {
            return View();
        }

        // POST: RestaurantTables/Create
        // To protect from overposting attacks, enable the specific properties you want to bind to.
        // For more details, see http://go.microsoft.com/fwlink/?LinkId=317598.
        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task<IActionResult> Create([Bind("TableNumber,MctId")] RestaurantTables restaurantTables)
        {
            if (ModelState.IsValid)
            {
                _context.Add(restaurantTables);
                await _context.SaveChangesAsync();
                await registerImagesMCT(restaurantTables.MctId,4);
                await registerImagesMCT(restaurantTables.MctId,5);
                await registerImagesMCT(restaurantTables.MctId,6);
                return RedirectToAction(nameof(Index));
            }
            return View(restaurantTables);
        }

        private async Task registerImagesMCT(string id, int action){
            
            string imageContent;

            switch (action){
                case 4:
                    imageContent = "data:image/png;base64,";
                    break;
                case 5:
                    imageContent = "data:image/png;base64,";
                    break;
                case 6:
                    imageContent = "data:image/png;base64,";
                    break;
                default:
                    imageContent = ""; // Default content
                    break;
            }
            
            // Create the body for the POST request
            var requestBody = new
            {
                device_id = id,
                action = action,
                content = imageContent
            };

            // Serialize the request body to JSON
            var jsonContent = JsonSerializer.Serialize(requestBody);
            var content = new StringContent(jsonContent, Encoding.UTF8, "application/json");

            // Create an HttpRequestMessage to include the custom header
            var requestMessage = new HttpRequestMessage(HttpMethod.Post, "https://mc-connect-manager.smcs.io/api/v1/registration/image/push-switch")
            {
                Content = content
            };

            // Add the custom Star-Api-Key header
            requestMessage.Headers.Add("Star-Api-Key", "00a7d7db-37e9-4737-8400-5c778d6cc05c");
            try
            {
                // Send the POST request
                var response = await _httpClient.SendAsync(requestMessage);

                // Check if the request was successful
                if (response.IsSuccessStatusCode)
                {
                    Console.WriteLine("Request succeeded.");
                    // Handle success (if needed)
                }
                else
                {
                    Console.WriteLine($"Request failed: {response.StatusCode}");
                    // Handle failure (e.g., log the error, throw an exception, etc.)
                }
            }
            catch (Exception ex)
            {
                // Handle any exceptions that occur during the request
                Console.WriteLine($"Exception: {ex.Message}");
            }
        }

        // GET: RestaurantTables/Edit/5
        public async Task<IActionResult> Edit(int? id)
        {
            if (id == null)
            {
                return NotFound();
            }

            var restaurantTables = await _context.RestaurantTables.FindAsync(id);
            if (restaurantTables == null)
            {
                return NotFound();
            }
            return View(restaurantTables);
        }

        // POST: RestaurantTables/Edit/5
        // To protect from overposting attacks, enable the specific properties you want to bind to.
        // For more details, see http://go.microsoft.com/fwlink/?LinkId=317598.
        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task<IActionResult> Edit(int id, [Bind("TableNumber,MctId")] RestaurantTables restaurantTables)
        {
            if (id != restaurantTables.TableNumber)
            {
                return NotFound();
            }

            if (ModelState.IsValid)
            {
                try
                {
                    _context.Update(restaurantTables);
                    await _context.SaveChangesAsync();
                }
                catch (DbUpdateConcurrencyException)
                {
                    if (!RestaurantTablesExists(restaurantTables.TableNumber))
                    {
                        return NotFound();
                    }
                    else
                    {
                        throw;
                    }
                }
                return RedirectToAction(nameof(Index));
            }
            return View(restaurantTables);
        }

        // GET: RestaurantTables/Delete/5
        public async Task<IActionResult> Delete(int? id)
        {
            if (id == null)
            {
                return NotFound();
            }

            var restaurantTables = await _context.RestaurantTables
                .FirstOrDefaultAsync(m => m.TableNumber == id);
            if (restaurantTables == null)
            {
                return NotFound();
            }

            return View(restaurantTables);
        }

        // POST: RestaurantTables/Delete/5
        [HttpPost, ActionName("Delete")]
        [ValidateAntiForgeryToken]
        public async Task<IActionResult> DeleteConfirmed(int id)
        {
            var restaurantTables = await _context.RestaurantTables.FindAsync(id);
            if (restaurantTables != null)
            {
                _context.RestaurantTables.Remove(restaurantTables);
            }

            await _context.SaveChangesAsync();
            return RedirectToAction(nameof(Index));
        }

        private bool RestaurantTablesExists(int id)
        {
            return _context.RestaurantTables.Any(e => e.TableNumber == id);
        }
    }
}
